/** Local immutable snapshots; warehouse queries and inventory.report are evidence, never stock setters. */
@Service public class WarehouseReconciliation {
 @Resource WmsStore db;@Resource WarehouseControlScope scope;@Resource StockMovementClient stock;@Resource WmsConnections connections;
 @Resource QimenWarehouseControlProtocol protocol;@Resource WmsInteractionLog logs;@Resource @Lazy WarehouseControlWork work;
 @Resource @Lazy WarehouseFullReconciliation full; @Resource WarehouseReconciliationGate gate;
 private long n(Map<String,Object>d,String k){return scope.n(d,k);}
 private Map<String,Object> get(String c,long id){return db.one("SELECT * FROM warehouse_reconciliation WHERE company_code=? AND id=?",c,id);}
 public Map<String,Object> list(String c,Map<String,String>q){return scope.page(c,"warehouse_reconciliation",q,"store_code,owner_code,real_store,method,scope_mode,coverage,progress_json,source_check_id,difference_count,attention_count,oms_snapshot_at,wms_snapshot_at,last_error");}
 public Map<String,Object> detail(String c,long id){Map<String,Object>d=get(c,id);for(String k:Arrays.asList("request_hash","scope_hash","lease_token","lease_until"))d.remove(k);Map<String,Object> range=scope.obj(d.remove("scope_json"));range.remove("warehouse_skus");d.put("scope",range);if(d.get("progress_json")!=null){Map<String,Object>p=scope.obj(d.remove("progress_json"));if("FULL".equals(d.get("scope_mode"))){p.put("total",n(d,"discovered_count"));p.put("successful",n(d,"successful_count"));p.put("failed",n(d,"failed_count"));p.put("result_rows",n(d,"result_count"));if(Arrays.asList("RUNNING","PENDING").contains(d.get("state")))p.remove("finished_at");}d.put("progress",p);}d.put("audit",scope.audit(c,"RECONCILIATION",id));d.put("route",scope.obj(d.remove("route_json")));if(d.get("result_json")!=null)d.put("result",scope.obj(d.remove("result_json")));List<Map<String,Object>>adjustments=db.jdbc.queryForList("SELECT id,document_sn,state,control_version,reason,evidence,created_by,reviewed_by,last_error,create_time FROM warehouse_stock_adjustment WHERE company_code=? AND reconciliation_id=? ORDER BY id DESC",c,id);for(Map<String,Object>a:adjustments)ReturnQueryWarehouse.formatTimes(a);d.put("adjustments",adjustments);d.put("interactions",db.jdbc.queryForList("SELECT id,action,result,error_info,duration_ms,create_time FROM wms_interaction_log WHERE company_code=? AND ticket_sn=? ORDER BY id DESC LIMIT 60",c,d.get("document_sn")));for(Map<String,Object>l:scope.rows(d.get("interactions")))ReturnQueryWarehouse.formatTimes(l);ReturnQueryWarehouse.formatTimes(d);return d;}
 public long create(String c,Map<String,Object>cmd,String actor){if("FULL".equals(cmd.get("scope_mode")))return full.create(c,cmd,actor);String key=required(cmd,"request_key",64),digest=scope.hash(cmd),store=required(cmd,"store_code",64),method=required(cmd,"method",32);List<String>skus=scope.skus(cmd.get("skus"));require(Arrays.asList("inventory.query","stock.query").contains(method),"请选择多商品查询或批次分页查询");require(!method.equals("stock.query")||skus.size()==1,"批次分页查询每任务选择一个SKU，最多5000行");Map<String,Object>w=scope.warehouse(c,store),route=scope.route(c,w);List<String>stores=scope.stores(c,w);scope.goods(c,skus);Map<String,Object>range=map("stores",stores,"skus",skus,"batch_code",text(cmd.get("batch_code")));return db.tx().execute(tx->{List<Map<String,Object>>old=db.jdbc.queryForList("SELECT id,request_hash FROM warehouse_reconciliation WHERE company_code=? AND request_key=?",c,key);if(!old.isEmpty()){require(digest.equals(old.get(0).get("request_hash")),"相同对账请求内容发生变化");return n(old.get(0),"id");}long id=db.insert("warehouse_reconciliation",map("company_code",c,"document_sn","DZ"+UUID.randomUUID().toString().replace("-",""),"request_key",key,"request_hash",digest,"store_code",store,"owner_code",w.get("actual_owner"),"real_store",w.get("real_store_code"),"method",method,"connection_id",route.get("connection_id"),"scope_json",db.encode(range),"scope_hash",scope.hash(range),"route_json",db.encode(route),"created_by",actor,"source_check_id",cmd.get("source_check_id")==null?0:cmd.get("source_check_id")));work.ready(c,id,false);return id;});}
 @SuppressWarnings("unchecked") private List<String>strings(Object o){return (List<String>)o;}
 private Map<String,String>versions(Map<String,Object>s){Map<String,String>r=new TreeMap<>();for(Map<String,Object>b:scope.rows(s.get("batches")))r.put("B/"+n(b,"id"),String.valueOf(n(b,"version")));for(Map<String,Object>b:scope.rows(s.get("totals")))r.put("S/"+b.get("sku_sn"),String.valueOf(n(b,"version")));return r;}
 /** Bounded local candidates; exact SKU predicates prevent unrelated warehouse activity from blocking this comparison. */
 public List<Map<String,Object>> pending(String c,Map<String,Object>range){List<String>stores=strings(range.get("stores")),skus=strings(range.get("skus"));String sm=String.join(",",Collections.nCopies(stores.size(),"?")),km=String.join(",",Collections.nCopies(skus.size(),"?"));List<String>queries=new ArrayList<>();List<Object>args=new ArrayList<>();
  queries.add("SELECT t.sn document_sn,'出入库尚未入账或待仓库确认' reason,t.wms_simulation_code store_code FROM wms_tickets t WHERE t.company_key=? AND t.wms_simulation_code IN("+sm+") AND t.actual_warehouse=1 AND t.inventory_status<>2 AND EXISTS(SELECT 1 FROM wms_tickets_goods g WHERE g.company_code=t.company_key AND g.sn=t.sn AND g.sku_sn IN("+km+"))");args.add(c);args.addAll(stores);args.addAll(skus);
  queries.add("SELECT r.return_sn,'采购退仓仍有仓库实物或入账待确认',r.store_code FROM purchase_return r WHERE r.company_code=? AND r.store_code IN("+sm+") AND r.state NOT IN('DRAFT','COMPLETED','CANCELED') AND EXISTS(SELECT 1 FROM purchase_return_line l WHERE l.company_code=r.company_code AND l.return_id=r.id AND l.sku_sn IN("+km+"))");args.add(c);args.addAll(stores);args.addAll(skus);
  queries.add("SELECT h.reclaim_sn,'供应商拒收收回仍有实收或入账待确认',h.store_code FROM purchase_return_reclaim h WHERE h.company_code=? AND h.store_code IN("+sm+") AND h.state IN('ACTIVE','CANCELING') AND EXISTS(SELECT 1 FROM purchase_return_line l JOIN purchase_return_reclaim_line x ON x.company_code=l.company_code AND x.return_line_id=l.id WHERE x.company_code=h.company_code AND x.reclaim_id=h.id AND l.sku_sn IN("+km+"))");args.add(c);args.addAll(stores);args.addAll(skus);
  queries.add("SELECT d.document_sn,'调拨两侧有未结束执行或在途实收待确认',d.source_store FROM warehouse_transfer d WHERE d.company_code=? AND (d.source_store IN("+sm+") OR d.target_store IN("+sm+")) AND d.state NOT IN('DRAFT','COMPLETED') AND EXISTS(SELECT 1 FROM warehouse_transfer_line l WHERE l.company_code=d.company_code AND l.transfer_id=d.id AND l.sku_sn IN("+km+") AND (l.quantity>l.out_quantity+l.released_quantity OR l.out_quantity>l.in_quantity+l.recovered_quantity))");args.add(c);args.addAll(stores);args.addAll(stores);args.addAll(skus);
  // Store processing may affect component SKUs kept in its immutable recipe, so conservatively show that warehouse's active process.
  queries.add("SELECT p.process_sn,'该仓仓内加工未结束，须核对投入产出',p.store_code FROM wms_process_order p WHERE p.company_code=? AND p.store_code IN("+sm+") AND p.state NOT IN('DRAFT','COMPLETED','STOPPED')");args.add(c);args.addAll(stores);
  return db.jdbc.queryForList("SELECT * FROM ("+String.join(" UNION ALL ",queries)+") candidates LIMIT 101",args.toArray());
 }
 public void process(String c,long id){Map<String,Object>d=get(c,id);if("FULL".equals(d.get("scope_mode"))){full.process(c,id);return;}if(n(d,"parent_id")>0)return;String token=UUID.randomUUID().toString();if(gate!=null&&!gate.acquire(c,d,token)){db.jdbc.update("UPDATE warehouse_reconciliation SET next_attempt_at=DATE_ADD(NOW(),INTERVAL 10 SECOND) WHERE company_code=? AND id=?",c,id);return;}try{processItem(c,id,()->{if(gate!=null)gate.renew(c,d,token);});}finally{if(gate!=null)gate.release(c,d,token);}}
 public void processItem(String c,long id,Runnable heartbeat){String lease=UUID.randomUUID().toString();if(db.jdbc.update("UPDATE warehouse_reconciliation SET state='RUNNING',lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND),attempts=attempts+1 WHERE company_code=? AND id=? AND state IN('PENDING','RUNNING','FAILED') AND (lease_until IS NULL OR lease_until<NOW())",lease,c,id)==0)return;
  try{Map<String,Object>d=get(c,id),range=scope.obj(d.get("scope_json")),route=scope.obj(d.get("route_json"));Map<String,Object>currentRoute=scope.route(c,scope.warehouse(c,text(d.get("store_code"))));for(String k:Arrays.asList("connection_id","external_owner","external_warehouse"))require(text(route.get(k)).equals(text(currentRoute.get(k))),"原对账路由已变化，请创建新对账");require(new TreeSet<>(strings(range.get("stores"))).equals(new TreeSet<>(scope.stores(c,scope.warehouse(c,text(d.get("store_code")))))),"同实仓虚仓范围发生变化，请新建库存检查");Map<String,Object>before=scope.snapshot(c,strings(range.get("stores")),strings(range.get("skus")));Map<String,Object>connection=connections.usable(c,n(route,"connection_id"));List<Map<String,Object>>wms=new ArrayList<>();boolean paged="stock.query".equals(d.get("method"));long total=-1;for(int page=1;page<=50;page++){heartbeat.run();require(db.jdbc.update("UPDATE warehouse_reconciliation SET lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=? AND lease_token=?",c,id,lease)==1,"对账执行租约已变化");Map<String,Object>req;if(paged)req=map("warehouseCode",route.get("external_warehouse"),"ownerCode",route.get("external_owner"),"itemCode",strings(range.get("skus")).get(0),"batchCode",range.get("batch_code"),"page",page,"pageSize",100,"extendProps",map("type",2));else{List<Map<String,Object>>criteria=new ArrayList<>();for(String sku:strings(range.get("skus")))criteria.add(map("warehouseCode",route.get("external_warehouse"),"ownerCode",route.get("external_owner"),"itemCode",sku));req=map("criteriaList",map("criteria",criteria));}WmsProtocol.Wire wire=protocol.wire(connection,connections.secret(connection),text(d.get("method")),req);long started=System.currentTimeMillis(),log=logs.start(c,n(connection,"id"),id,text(d.get("document_sn")),"OUT","STOCK_QUERY",wire.body);try{String response=WmsHttp.post(wire);Map<String,Object>r=protocol.inventory(response,text(route.get("external_warehouse")),text(route.get("external_owner")),paged);logs.finish(log,"SUCCESS",response,"",System.currentTimeMillis()-started);List<Map<String,Object>>part=scope.rows(r.get("rows"));wms.addAll(part);if(!paged)break;require(r.get("total")!=null,"批次分页库存缺少totalCount，不能确认结果完整");if(total<0)total=n(r,"total");require(total==n(r,"total")&&total<=5000,"库存分页总数变化或超过5000行，请缩小范围");if(wms.size()>=total){require(wms.size()==total,"仓库分页数量超过声明总数");break;}require(part.size()==100&&page<50,"库存分页未完整返回，请重新查询");}catch(Exception e){logs.finish(log,"FAILED","",scope.safe(e),System.currentTimeMillis()-started);throw e;}}
   Map<String,Object>after=scope.snapshot(c,strings(range.get("stores")),strings(range.get("skus")));List<Map<String,Object>>pending=pending(c,range);if(!versions(before).equals(versions(after)))pending.add(map("document_sn","本次查询期间库存变化","reason","OMS快照版本发生变化，请等待入账后重新检查"));Map<String,Object>result=compare(after,wms,range,pending);Map<String,Map<String,Object>>goods=scope.checkGoods(c,strings(range.get("skus")));for(Map<String,Object>r:scope.rows(result.get("rows"))){Map<String,Object>g=goods.getOrDefault(text(r.get("sku_sn")),Collections.emptyMap());r.put("stock_unit","套".equals(text(g.get("stock_unit")))?"套":"件");r.put("goods_name",g.get("goods_name"));if(g.isEmpty()){r.put("stock_unit","");r.put("catalog_missing",true);result.put("can_adjust",false);}}db.jdbc.update("UPDATE warehouse_reconciliation SET state='COMPLETED',result_json=?,difference_count=?,attention_count=?,oms_snapshot_at=?,wms_snapshot_at=NOW(),last_error='' WHERE company_code=? AND id=?",db.encode(result),result.get("difference_count"),result.get("attention_count"),java.sql.Timestamp.valueOf(text(after.get("snapshot_at")).replace('T',' ')),c,id);
  }catch(Exception e){db.jdbc.update("UPDATE warehouse_reconciliation SET state='FAILED',last_error=?,next_attempt_at=DATE_ADD(NOW(),INTERVAL LEAST(300,attempts*15) SECOND) WHERE company_code=? AND id=?",scope.safe(e),c,id);}finally{db.jdbc.update("UPDATE warehouse_reconciliation SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,id,lease);}}
 private String key(String sku,String batch,String type){return sku+"\u001f"+batch+"\u001f"+type;}
 public Map<String,Object> compare(Map<String,Object>oms,List<Map<String,Object>>wms,Map<String,Object>range,List<Map<String,Object>>pending){Map<String,Map<String,Object>>index=new TreeMap<>();List<String>skus=strings(range.get("skus"));String filter=text(range.get("batch_code"));for(Map<String,Object>b:scope.rows(oms.get("batches"))){if(!filter.isEmpty()&&!filter.equals(b.get("batch_code")))continue;for(String type:Arrays.asList("ZP","CP")){String p=type.equals("ZP")?"zp":"cp";if(n(b,p+"_actual_number")==0&&n(b,p+"_lock_number")==0)continue;String k=key(text(b.get("sku_sn")),text(b.get("batch_code")),type);Map<String,Object>r=index.computeIfAbsent(k,x->map("key",k,"sku_sn",b.get("sku_sn"),"batch_code",b.get("batch_code"),"inventory_type",type,"oms_physical",0L,"oms_held",0L,"wms_physical",null,"wms_frozen",null,"status","MISSING_WMS","sources",new ArrayList<Map<String,Object>>()));r.put("oms_physical",n(r,"oms_physical")+n(b,p+"_actual_number"));r.put("oms_held",n(r,"oms_held")+n(b,p+"_lock_number"));scope.rows(r.get("sources")).add(map("store_code",b.get("store_code"),"batch_id",b.get("id"),"unit_cost",b.get("transaction_price"),"physical",b.get(p+"_actual_number"),"free",b.get(p+"_available_number")));}}
  Set<String>seen=new HashSet<>();for(Map<String,Object>w:wms){String sku=text(w.get("sku_sn")),batch=text(w.get("batch_code")),raw=text(w.get("inventory_type")),type=raw.equals("CC")?"CP":raw;require(skus.contains(sku),"库存响应含本次查询范围外的SKU");if(!filter.isEmpty()&&!filter.equals(batch))continue;String k=key(sku,batch,type);require(seen.add(k),"同一商品批次质量返回多行，需先核对是否按渠道重复返回");Map<String,Object>r=index.computeIfAbsent(k,x->map("key",k,"sku_sn",sku,"batch_code",batch,"inventory_type",type,"oms_physical",0L,"oms_held",0L,"sources",new ArrayList<Map<String,Object>>()));r.put("wms_physical",w.get("physical"));r.put("wms_frozen",w.get("frozen"));r.put("wms_unfrozen",w.get("unfrozen"));r.put("status",!Arrays.asList("ZP","CP").contains(type)?"UNSUPPORTED_TYPE":batch.isEmpty()?"MISSING_BATCH":w.get("physical")==null?"MISSING_FIELDS":"COMPARED");}
  // Absence of a SKU is unknown, including an empty successful warehouse response.
  for(String sku:skus)if(index.values().stream().noneMatch(r->sku.equals(r.get("sku_sn"))))index.put(key(sku,"",""),map("sku_sn",sku,"batch_code","","inventory_type","","oms_physical",0,"wms_physical",null,"status","MISSING_WMS","sources",Collections.emptyList()));
  long differences=0,attention=0;for(Map<String,Object>r:index.values()){String status=text(r.get("status"));if(status.equals("COMPARED")){long delta=n(r,"wms_physical")-n(r,"oms_physical");r.put("difference",delta);r.put("frozen_difference",n(r,"wms_frozen")-n(r,"oms_held"));if(n(r,"frozen_difference")!=0)attention++;if(delta!=0){differences++;status=pending.isEmpty()?"PHYSICAL_DIFFERENCE":"WAITING_POST";}else if(n(r,"frozen_difference")!=0){status="FROZEN_CHECK";}else status="MATCHED";}else attention++;r.put("status",status);}
  return map("rows",new ArrayList<>(index.values()),"oms",oms,"wms",wms,"pending_documents",pending,"difference_count",differences,"attention_count",attention,"can_adjust",differences>0&&attention==0&&pending.isEmpty(),"formula","WMS实物=未冻结+冻结；OMS同货主同实仓全部虚仓实物合计。OMS业务占用与WMS冻结分别核查，差额不直接改账。");
 }
 public Map<String,Object> retry(String c,long id){Map<String,Object>d=get(c,id);require(n(d,"parent_id")==0&&!"FULL".equals(d.get("scope_mode")),"全仓及商品子快照请返回全仓任务恢复或重试失败商品");require("FAILED".equals(d.get("state")),"仅查询失败任务可以原单重试；检查新库存请创建新对账快照");db.jdbc.update("UPDATE warehouse_reconciliation SET state='PENDING',next_attempt_at=NOW() WHERE company_code=? AND id=? AND state='FAILED'",c,id);work.ready(c,id,false);return detail(c,id);}
 public long adjustment(String c,long id,Map<String,Object>cmd,String actor){Map<String,Object>d=get(c,id);require(!"FULL".equals(d.get("scope_mode"))&&n(d,"parent_id")==0,"全仓结果仅用于发现差异，请先创建选定商品的最新复查");Map<String,Object>result=scope.obj(d.get("result_json")),range=scope.obj(d.get("scope_json"));require("COMPLETED".equals(d.get("state"))&&Boolean.TRUE.equals(result.get("can_adjust")),"字段缺失、冻结待核对或待入账时不能申请实物调整");require(pending(c,range).isEmpty(),"目前存在尚未结束或待入账的单据，请先核查后重新对账");String key=required(cmd,"request_key",64),reason=required(cmd,"reason",1000),evidence=required(cmd,"evidence",1000),digest=scope.hash(cmd);Map<String,Long>expected=new TreeMap<>(),chosen=new TreeMap<>();for(Map<String,Object>r:scope.rows(result.get("rows")))if(n(r,"difference")!=0)expected.put(text(r.get("key")),n(r,"difference"));List<Map<String,Object>>lines=scope.rows(cmd.get("lines"));require(!lines.isEmpty()&&lines.size()<=200,"调整明细须为1至200行");for(Map<String,Object>l:lines){String k=key(required(l,"sku_sn",128),required(l,"batch_code",128),required(l,"inventory_type",2));require(expected.containsKey(k)&&strings(range.get("stores")).contains(text(l.get("store_code")))&&n(l,"quantity")!=0&&Long.signum(n(l,"quantity"))==Long.signum(expected.get(k)),"调整只能处理本次已核实实物差异，须明确实际归属虚仓");chosen.merge(k,n(l,"quantity"),Math::addExact);require(l.get("unit_cost")!=null&&new java.math.BigDecimal(l.get("unit_cost").toString()).signum()>=0,"请明确原批次成本或盘盈成本凭证");}require(expected.equals(chosen),"各批次质量的调整合计须与对账差额完全一致");return db.tx().execute(tx->{db.one("SELECT id FROM warehouse_reconciliation WHERE company_code=? AND id=? FOR UPDATE",c,id);List<Map<String,Object>>old=db.jdbc.queryForList("SELECT id,request_hash FROM warehouse_stock_adjustment WHERE company_code=? AND request_key=?",c,key);if(!old.isEmpty()){require(digest.equals(old.get(0).get("request_hash")),"相同调整申请内容变化");return n(old.get(0),"id");}long adjustment=db.insert("warehouse_stock_adjustment",map("company_code",c,"document_sn","TZ"+UUID.randomUUID().toString().replace("-",""),"reconciliation_id",id,"request_key",key,"request_hash",digest,"payload_json",db.encode(map("snapshot",result.get("oms"),"lines",lines)),"reason",reason,"evidence",evidence,"created_by",actor));scope.audit(c,"RECONCILIATION",id,"ADJUSTMENT_CREATE",actor,"调整申请#"+adjustment+"；"+reason+"；凭证："+evidence);return adjustment;});}
 public Map<String,Object> review(String c,long adjustment,Map<String,Object>cmd,String actor){Map<String,Object>hint=db.one("SELECT * FROM warehouse_stock_adjustment WHERE company_code=? AND id=?",c,adjustment);Map<String,Object>d=get(c,n(hint,"reconciliation_id"));require(pending(c,scope.obj(d.get("scope_json"))).isEmpty(),"存在待入账单据，请先核查");String decision=required(cmd,"decision",16);require(Arrays.asList("APPROVE","REJECT").contains(decision),"审核选择无效");db.tx().execute(tx->{Map<String,Object>a=db.one("SELECT * FROM warehouse_stock_adjustment WHERE company_code=? AND id=? FOR UPDATE",c,adjustment);scope.version(a,cmd);require("DRAFT".equals(a.get("state")),"调整已经审核");db.jdbc.update("UPDATE warehouse_stock_adjustment SET state=?,reviewed_by=?,control_version=control_version+1 WHERE company_code=? AND id=?",decision.equals("APPROVE")?"APPROVED":"REJECTED",actor,c,adjustment);scope.audit(c,"RECONCILIATION",n(a,"reconciliation_id"),decision.equals("APPROVE")?"ADJUSTMENT_APPROVE":"ADJUSTMENT_REJECT",actor,text(a.get("document_sn"))+"；"+text(a.get("evidence")));return null;});if(decision.equals("APPROVE"))work.adjustmentReady(c,adjustment);return detail(c,n(hint,"reconciliation_id"));}
 public void postAdjustment(String c,long adjustment){String lease=UUID.randomUUID().toString();if(db.jdbc.update("UPDATE warehouse_stock_adjustment SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 120 SECOND),attempts=attempts+1 WHERE company_code=? AND id=? AND state='APPROVED' AND (lease_until IS NULL OR lease_until<NOW())",lease,c,adjustment)==0)return;try{Map<String,Object>a=db.one("SELECT * FROM warehouse_stock_adjustment WHERE company_code=? AND id=?",c,adjustment),d=get(c,n(a,"reconciliation_id"));require(pending(c,scope.obj(d.get("scope_json"))).isEmpty(),"存在待入账实物单据，请先核查");Map<String,Object>payload=scope.obj(a.get("payload_json"));payload.putAll(map("document_sn",a.get("document_sn"),"actor",a.get("reviewed_by"),"evidence",a.get("evidence")));scope.reply(stock.execute(c,"adjust",payload));db.jdbc.update("UPDATE warehouse_stock_adjustment SET state='POSTED',last_error='' WHERE company_code=? AND id=?",c,adjustment);}catch(Exception e){db.jdbc.update("UPDATE warehouse_stock_adjustment SET last_error=?,next_attempt_at=DATE_ADD(NOW(),INTERVAL LEAST(300,attempts*15) SECOND) WHERE company_code=? AND id=?",scope.safe(e),c,adjustment);}finally{db.jdbc.update("UPDATE warehouse_stock_adjustment SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,adjustment,lease);}}
 public String callback(String c,String key,Map<String,String>params,String body){Map<String,Object>connection=db.one("SELECT * FROM wms_connection WHERE company_code=? AND callback_key=?",c,key);long start=System.currentTimeMillis(),log=logs.start(c,n(connection,"id"),null,"","IN","STOCK_REPORT",body);try{Map<String,Object>r=protocol.inventoryReport(connection,connections.secret(connection),params,body);require(text(r.get("message_id")).length()<=128&&!text(r.get("owner_code")).isEmpty()&&!text(r.get("warehouse_code")).isEmpty(),"盘点通知身份缺失或过长");require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_simulation_store_info WHERE company_key=? AND connection_id=? AND external_owner=? AND external_warehouse=?",Long.class,c,connection.get("id"),r.get("owner_code"),r.get("warehouse_code"))>0,"盘点通知仓库货主未绑定本连接");String digest=scope.hash(r);db.tx().execute(tx->{List<Map<String,Object>>old=db.jdbc.queryForList("SELECT payload_hash FROM warehouse_inventory_report WHERE company_code=? AND connection_id=? AND message_id=? FOR UPDATE",c,connection.get("id"),r.get("message_id"));if(!old.isEmpty())require(digest.equals(old.get(0).get("payload_hash")),"相同盘点通知内容变化");else db.insert("warehouse_inventory_report",map("company_code",c,"connection_id",connection.get("id"),"message_id",r.get("message_id"),"payload_hash",digest,"owner_code",r.get("owner_code"),"warehouse_code",r.get("warehouse_code"),"check_order",r.get("check_order"),"payload_json",db.encode(r),"source_log_id",log));return null;});db.jdbc.update("UPDATE wms_interaction_log SET ticket_sn=? WHERE id=?",r.get("check_order"),log);String response=new QimenProtocol().acknowledgement(true,"盘点证据已保存，请对账核查并独立审核差异调整");logs.finish(log,"SUCCESS",response,"",System.currentTimeMillis()-start);return response;}catch(Exception e){String response=new QimenProtocol().acknowledgement(false,scope.safe(e));logs.finish(log,"FAILED",response,scope.safe(e),System.currentTimeMillis()-start);return response;}}
 public Map<String,Object> reports(String c){List<Map<String,Object>>rs=db.jdbc.queryForList("SELECT id,connection_id,message_id,owner_code,warehouse_code,check_order,payload_json,source_log_id,create_time FROM warehouse_inventory_report WHERE company_code=? ORDER BY id DESC LIMIT 100",c);for(Map<String,Object>r:rs){r.put("report",scope.obj(r.remove("payload_json")));ReturnQueryWarehouse.formatTimes(r);}return map("rows",rs);}
 public int scan(String c){List<Long>ids=db.jdbc.queryForList("SELECT id FROM warehouse_reconciliation WHERE company_code=? AND parent_id=0 AND (state IN('PENDING','RUNNING','STOPPING') OR (scope_mode<>'FULL' AND state='FAILED' AND attempts<5)) AND next_attempt_at<=NOW() AND (lease_until IS NULL OR lease_until<NOW()) ORDER BY next_attempt_at,id LIMIT 20",Long.class,c);for(long id:ids)work.ready(c,id,false);for(long id:db.jdbc.queryForList("SELECT id FROM warehouse_stock_adjustment WHERE company_code=? AND state='APPROVED' AND attempts<5 AND next_attempt_at<=NOW() AND (lease_until IS NULL OR lease_until<NOW()) ORDER BY next_attempt_at,id LIMIT 20",Long.class,c))work.adjustmentReady(c,id);return ids.size();}
}
